import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (pos < buf.length && buf[pos] <= 32) pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > 32) pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= 32) pos++;
        boolean neg = buf[pos] == 45;
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > 32) r = r * 10 + (buf[pos++] - 48);
        return neg ? -r : r;
    }

    static int nextInt() { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long m = nextLong();
        PriorityQueue<Long> heap = new PriorityQueue<>(Collections.reverseOrder());
        for (int i = 0; i < n; i++) heap.add(nextLong());
        long revenue = 0;
        for (long i = 0; i < m; i++) {
            long q = heap.poll();
            revenue += q;
            if (q > 1) heap.add(q - 1);
        }
        System.out.println(revenue);
    }
