package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
	"container/heap"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

type maxHeap []int64

func (h maxHeap) Len() int           { return len(h) }
func (h maxHeap) Less(i, j int) bool { return h[i] > h[j] }
func (h maxHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *maxHeap) Push(x any)        { *h = append(*h, x.(int64)) }
func (h *maxHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	n, m := int(nextInt()), nextInt()
	h := make(maxHeap, n)
	for i := range h {
		h[i] = nextInt()
	}
	heap.Init(&h)
	var revenue int64
	for i := int64(0); i < m; i++ {
		q := h[0]
		revenue += q
		if q > 1 {
			h[0] = q - 1
			heap.Fix(&h, 0)
		} else {
			heap.Pop(&h)
		}
	}
	w.WriteString(strconv.FormatInt(revenue, 10) + "\n")
}
